#!/usr/bin/env node
/* The platform deploys each function alone (functions/ is its source directory), so a shared library cannot be
   resolved at run time. This step puts the one module the subscribe action needs, `@krizaka/rate-limit/turnstile`
   (dependency-free, an ES module), next to it as `turnstile.mjs`, byte for byte under a generated header.
   `npm run functions:bundle` writes it; `--check` (the unit test) fails when the committed file drifted from the
   installed version. Never edit the generated file: bump the package and run the step.
   Same step for the confirmation e-mail: @krizaka/email renders it (EN and FR) into confirmation-emails.json, the subscribe
   action only fills in the signed link and the postal address. */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { createRequire } from "node:module";
import { renderConfirmationEmail } from "./newsletter-email.mjs";

const SOURCE = new URL("../node_modules/@krizaka/rate-limit/dist/turnstile.js", import.meta.url);
const PACKAGE = new URL("../node_modules/@krizaka/rate-limit/package.json", import.meta.url);
export const EMAILS = new URL("../functions/packages/newsletter/subscribe/confirmation-emails.json", import.meta.url);
export const TARGET = new URL("../functions/packages/newsletter/subscribe/turnstile.mjs", import.meta.url);
/* The cookieless visit count (krizaka-internal#4122): `@krizaka/visits`, whose main entry imports nothing, next to the count action. */
const VISITS_SOURCE = new URL("../node_modules/@krizaka/visits/dist/index.js", import.meta.url);
const VISITS_PACKAGE = new URL("../node_modules/@krizaka/visits/package.json", import.meta.url);
export const VISITS_TARGET = new URL("../functions/packages/visits/count/visits.mjs", import.meta.url);

export function render(source_ = SOURCE, package_ = PACKAGE, name = "@krizaka/rate-limit", part = "turnstile") {
  const source = readFileSync(source_, "utf8");
  const map = source.lastIndexOf("\n//# sourceMappingURL=");
  const code = map === -1 ? source : `${source.slice(0, map)}\n`;
  if (/^[ \t]*import[ \t{]/m.test(code))
    throw new Error(`${name} (${part}) now imports something: a real bundler is needed`);
  const { version } = JSON.parse(readFileSync(package_, "utf8"));
  return `// GENERATED by scripts/bundle-functions.mjs from ${name}@${version} (${part}). Do not edit.\n${code}`;
}

/** The confirmation e-mail of each language, as the file holds it. The window is the function's own constant. */
export async function renderEmails() {
  const { CONFIRM_TTL_MS } = createRequire(import.meta.url)("../functions/packages/newsletter/subscribe/newsletter.js");
  const hours = CONFIRM_TTL_MS / 3_600_000;
  const out = {};
  for (const locale of ["en", "fr"]) out[locale] = await renderConfirmationEmail(locale, hours);
  return `${JSON.stringify(out, null, 2)}\n`;
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  const files = [
    [TARGET, render()],
    [VISITS_TARGET, render(VISITS_SOURCE, VISITS_PACKAGE, "@krizaka/visits", "visit count")],
    [EMAILS, await renderEmails()],
  ];
  if (process.argv.includes("--check")) {
    const stale = files.filter(([file, text]) => !existsSync(file) || readFileSync(file, "utf8") !== text);
    if (stale.length) {
      console.error(
        `out of date: ${stale.map(([f]) => f.pathname.split("/").pop()).join(", ")}; run \`npm run functions:bundle\``,
      );
      process.exit(1);
    }
  } else {
    for (const [file, text] of files) writeFileSync(file, text);
    console.log("wrote", files.map(([f]) => f.pathname.split("/").pop()).join(", "));
  }
}
